\label{E}\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ 

\begin{enumerate}
\item Let $A=\ell^{1}(\mathbb{Z)}$ be the Banach lattice algebra with
pointwise multiplication
\[
x.y(n)=x_{n}y_{n}\text{ for all }x,y\in A\text{ and }n\in\mathbb{N}\text{.} 
\]
Then, $\mathcal{L}$-\textrm{$wap$}$(A)=c_{0}$.

If $\ell^{1}(\mathbb{Z)}$ is furnished with convolution product defined by
\[
(x.y)(n)= 
                                          
               
{\displaystyle\sum\limits_{k\in\mathbb{Z}}}
             
x(k)y(n-k)\text{ for all }x,y\in A\text{ and }n\in\mathbb{Z}\text{,} 
\]
Then $\mathcal{L}$-\textrm{$wap$}$(A)=\left\{  0\right\}  $.

\item $(\ell^{1}$-direct sum of Banach lattice algebras).

Let $(A_{n})_{n}$ be a sequence of Banach lattice algebras and consider their
\ $\ell^{1}$-direct sum
\[
A=\bigoplus\limits_{n=1}^{\infty}A_{n}=\left\{  x=(x_{n})_{n}:x_{n}\in
A_{n}\text{ and }\left\Vert x\right\Vert =\sum\limits_{n=1}^{\infty}\left\Vert
x_{n}\right\Vert <+\infty\right\}  \text{,} 
\]
With coordinatewise product
\[
x.y=(x_{1}y_{1},x_{2}y_{2},..)\text{ for all }x=(x_{n})\text{ }y=(y_{n})\in
A\text{.} 
\]
Then $A$ is a Banach lattice algebra. Moreover, the dual space $A^{\prime}$ is
given by
\[
A^{\prime}=\bigoplus\limits_{n=1}^{\infty}A_{n}=\left\{  f=(f_{n}):f_{n}\in
A_{n}^{\prime}\text{ and }\left\Vert f\right\Vert _{\infty}=\sup\left\Vert
f_{n}\right\Vert <+\infty\right\}  \text{.} 
\]


For every $f=(f_{n})\in A^{\prime}$ and $x=(x_{n})$, $f.x=(f_{1}.x_{1} 
,f_{2}.x_{2},...)$. So, the orbit decomposes coordinatewise $O_{f}=O_{f_{1} 
}\times O_{f_{2}}\times..$. Consequently,
\begin{align*}
\mathrm{wap}(A_{1}\oplus A_{2}\oplus...)_{1}  &  =\mathrm{wap}(A_{1} 
)\oplus\mathrm{wap}(A_{2})\oplus...\\
\mathcal{L}-\mathrm{wap}(A_{1}\oplus A_{2}\oplus...)_{1}  &  =\mathcal{L} 
-\mathrm{wap}(A_{1})\oplus\mathcal{L}-\mathrm{wap}(A_{2})\oplus...
\end{align*}

\end{enumerate}

\bigskip Let $A=\ell^{1}(\mathbb{N)}$ with the multiplication defined by 
\[
x.y=(\sum\limits_{k=0}^{\infty}x_{k})(\sum\limits_{k=0}^{\infty}y_{k})v\text{
where }v=\frac{1}{2}(1,1,0,0,..)\text{.} 
\]
It is easy to check that $\ell^{1}$is a commutative Banach lattice algebra.
For $f\in A^{\prime}=\ell^{\infty}$, we have $f\circ x:y\longmapsto
(\sum\limits_{k=0}^{\infty}x_{k})(\sum\limits_{k=0}^{\infty}y_{k})f(v)$ for
all $f\in\ell^{\infty}$ and $x\in A$. Let $f=(1,-1,0,0,...)\in\ell^{\infty}$.
Then $f\in$ $\mathcal{L}$-\textrm{$wap$}$(A)$, since $O_{f}=\left\{
0\right\}  $, however $\left\vert f\right\vert =(1,1,0,0,..)\notin\mathcal{L} 
$-\textrm{$wap$}$(A)$, because, for the standard basis of $\ell^{1}$,
$\left\Vert \left\vert f\right\vert \circ e_{n}\right\Vert _{\infty
}=1\nrightarrow0$.

Suppose that $x\perp x^{\prime}\in A$. Then
\begin{align*}
\left\vert x\right\vert \otimes\left\vert y\right\vert \wedge\left\vert
x^{\prime}\right\vert \otimes\left\vert y\right\vert  &  \leq\left\vert
x\right\vert \otimes(\left\vert y\right\vert \vee\left\vert y^{\prime
}\right\vert )\wedge\left\vert x^{\prime}\right\vert \otimes(\left\vert
y\right\vert \vee\left\vert y^{\prime}\right\vert )\\
&  =\left\vert x\right\vert \wedge\left\vert x^{\prime}\right\vert
\otimes(\left\vert y\right\vert \vee\left\vert y^{\prime}\right\vert
)=0\text{,} 
\end{align*}
and therefore, $x\otimes y\perp x^{\prime}\otimes y^{\prime}$.

Conversely, assume that $\left\vert x\right\vert \otimes\left\vert
y\right\vert \wedge\left\vert x^{\prime}\right\vert \otimes\left\vert
y^{\prime}\right\vert =0$. From the inequality
\[
\left\vert x\right\vert \wedge\left\vert x^{\prime}\right\vert \otimes
\left\vert y\right\vert \wedge\left\vert y^{\prime}\right\vert \leq\left\vert
x\right\vert \otimes\left\vert y\right\vert \wedge\left\vert x^{\prime
}\right\vert \otimes\left\vert y^{\prime}\right\vert =0\text{,} 
\]
it follows that $\left\vert x\right\vert \wedge\left\vert x^{\prime
}\right\vert \otimes\left\vert y\right\vert \wedge\left\vert y^{\prime
}\right\vert =0$ . Thus, $\left\vert x\right\vert \wedge\left\vert x^{\prime
}\right\vert =0$ or $\left\vert y\right\vert \wedge\left\vert y^{\prime
}\right\vert =0$.

\label{KK}Let $f\in(A\otimes_{\left\vert \pi\right\vert }B)^{\prime}$. Then
the following assertions are equivalent:

\begin{description}
\item[(1)] $f\in\mathcal{L}$-\textrm{wap}$(A\otimes_{\left\vert \pi\right\vert
}B)$

\item[(2)] The set $W_{f}=\left\{  f.x\otimes y:0\leq x\in B_{A}\text{,}0\leq
y\in B_{B}\right\}  $ is $L$-weakly compact.

\item[(3)] For every positive sporadically disjoint sequence $(x_{n} 
,y_{n})\subset B_{A\times B}$ and every sequence $(x_{n}^{\prime} 
,y_{n}^{\prime})\subseteq B_{A\times B}$
\[
f(x_{n}^{\prime}x_{n}\otimes y_{n}^{\prime}y_{n})\longrightarrow0
\]

\end{description}

\label{PPP}

\begin{enumerate}
\item $f\in\mathcal{L}$-$\mathrm{wap}(A)$, $g\in\mathcal{L}$-$\mathrm{wap} 
(B)\Longrightarrow f\otimes g\in\mathcal{L}$-$\mathrm{wap}(A\otimes
_{\left\vert \pi\right\vert }B)$.

\item $f\otimes g\in\mathcal{L}$-$\mathrm{wap}(A\otimes_{\left\vert
\pi\right\vert }B)$, $g_{/B^{2}}\neq0$ $\Longrightarrow$ $f\in\mathcal{L} 
$-$\mathrm{wap}(A)$.

\item $f\otimes g\in\mathrm{wap}(A\otimes_{\left\vert \pi\right\vert }B)$,
$g_{/B^{2}}\neq0\Longrightarrow$ $f\in\mathrm{wap}(A)$
\end{enumerate}

\ \ \ \ \ \ \ \ \ 

\begin{enumerate}
\item Let $(x_{n},y_{n})$ be a positive sporadically disjoint sequence in
$B_{A}\times B_{B}$, and let $(x_{n}^{\prime},y_{n}^{\prime})$ be \ a sequence
in$\ B_{A}\times B_{B}$. We must show $\alpha_{n}=f(x_{n}^{\prime} 
x_{n})g(y_{n}^{\prime}y_{n})\longrightarrow0$. Suppose, to the contrary, that
this is not the case. Then, after passing to a subsequence, there exists
$\varepsilon>0$ such that~$\left\vert f(x_{n}^{\prime}x_{n})g(y_{n}^{\prime
}y_{n})\right\vert \geq\varepsilon$, for each $n$. For each $n\neq m$, either
$x_{n}\perp x_{m}$ or $y_{n}\perp y_{m}$. By Ramsey's theorem, there is an
infinite subsequence $(n_{k})$ such that either $(x_{n_{k}})$ is disjoint in
$A$ or $(y_{n_{k}})$ is disjoint in $B$. In the firt case, since
$f\in\mathcal{L}$-$\mathrm{wap}(A)$, $f(x_{n_{k}}^{\prime}x_{n_{k} 
})\longrightarrow0$. In the second case, since $g\in\mathcal{L}$ 
-$\mathrm{wap}(B)$, $g(y_{n_{k}}^{\prime}y_{n_{k}})\longrightarrow0$. In
either case, $\ f(x_{n_{k}}^{\prime}x_{n_{k}})g(y_{n_{k}}^{\prime}y_{n_{k} 
})\longrightarrow0$, contradicting the choice of the subsequence. Hence
$f\otimes g\in\mathcal{L}$-\textrm{$wap($}$A\otimes_{\left\vert \pi\right\vert
}B)$.

\item Since $g_{/B^{2}}\neq0$, there exists $0\leq u,v\in B_{B}$ such that
$g(uv)\neq0$. Let $(x_{n})\subset B_{A}$ be a disjoint sequence and
$(y_{n})\subset$ $B_{A}$. Consider the sequences $(x_{n},u)$ and $(y_{n},v)$
in $A\times B$. Since $x_{n}\perp x_{m}$ for $n\neq m$, $(x_{n},u)$ is
positive sporadically disjoint. Hence, by the $L$-weakly almost periodicity of
$f\otimes g$,
\[
(f\otimes g)(y_{n}x_{n}\otimes vu)\longrightarrow0\text{.} 
\]
Thus $f(y_{n}x_{n})g(uv)\longrightarrow0$. It follows that $f(y_{n} 
x_{n})\longrightarrow0$, so $f\in\mathcal{L}$-$\mathrm{wap}(A)$.

\item Let $(a_{n}),$ $(a_{m}^{\prime})\subset B_{A}$ be such that the iterated
limits $\lim\limits_{m}\lim\limits_{n}f(a_{n}a_{m}^{\prime})=\alpha$ and
$\lim\limits_{n}\lim\limits_{m}f(a_{n}a_{m}^{\prime})=\beta$, exist. Choose
$u,v\in B$ with $g(uv)\neq0$. Define $u_{n}=a_{n}\otimes u$ and $v_{m} 
=a_{m}\otimes v$. Then $(u_{n})$ and $(v_{m})$ are bounded in $A\otimes
_{\left\vert \pi\right\vert }B$ . Consequently
\begin{align*}
\lim_{m}\lim_{n}(f\otimes g)(u_{n}v_{n})  &  =\alpha g(uv)\text{ and }\\
\lim_{n}\lim_{m}(f\otimes g)(u_{n}v_{m})  &  =\beta g(uv)\text{.} 
\end{align*}
Since $f\otimes g$ is wap, the two iterated limits coincide. Hence
$\alpha=\beta$, and therefore $f\in$\textrm{$wap$}$(A)$.
\end{enumerate}

\label{F}Let $A$ and $B$ be non trivial Banach lattice algebras.

\begin{enumerate}
\item If $\mathcal{L}$-\textrm{$wap$}$(A\otimes_{\left\vert \pi\right\vert
}B)=(A\otimes_{\left\vert \pi\right\vert }B)^{\prime}$ then $\mathcal{L} 
$-\textrm{$wap$}$(A)=A^{\prime}$ and $\mathcal{L}$-\textrm{$wap$ 
}$(B)=B^{\prime}$.

\item If \textrm{$wap$}$(A\otimes_{\left\vert \pi\right\vert }B)=(A\otimes
_{\left\vert \pi\right\vert }B)^{\prime}$ then \textrm{$wap$}$(A)=A^{\prime}$
and \textrm{$wap$}$(B)=B^{\prime}$.
\end{enumerate}

In particular, if $A\otimes_{\left\vert \pi\right\vert }B$ is Arens regular,
then both $A$ and $B$ are Arens regular.

\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ 

\begin{enumerate}
\item Assume that $\mathcal{L}$-\textrm{$wap$}$(A\otimes_{\left\vert
\pi\right\vert }B)=(A\otimes_{\left\vert \pi\right\vert }B)^{\prime}$. Let
$f\in A^{\prime}$. Since $B$ is nontrivial, $B^{2}\neq\left\{  0\right\}  $.
Hence, there exists $g\in B^{\prime}$ such that $g_{/B^{2}}\neq0$. By
proposition \ref{PPP}, applied to $f\otimes g$, we obtain $f\in\mathcal{L} 
$-\textrm{$wap$}$(A)$. A symmetric argument shows that $\mathcal{L} 
$-\textrm{$wap$}$(B)=B^{\prime}$.

\item The proof is identical.
\end{enumerate}

Finally, if $A\otimes_{\left\vert \pi\right\vert }B$ is Arens regular, then
\textrm{$wap$}$(A\otimes_{\left\vert \pi\right\vert }B)=(A\otimes_{\left\vert
\pi\right\vert }B)^{\prime}$. Therefore, by part (2) \textrm{$wap$ 
}$(A)=A^{\prime}$ and \textrm{$wap$}$(B)=B^{\prime}$, so $A$ and $B$ are Arens regular.
